insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_SRC_COL_MPNG' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'COL_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'COL_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_SRC_COL_MPNG_02' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
