insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '등록 일시', null, null, false, 4, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '등록 일시');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '수정 일시', null, null, false, 5, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정 일시');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '등록자 아이디', null, null, false, 6, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '등록자 아이디');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), e.LGCL_ENTT_SN, '수정자 아이디', null, null, false, 7, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정자 아이디');
insert into TB_LGCL_IDNTFR(LGCL_IDNTFR_SN, LGCL_ENTT_SN, IDNTFR_NM, BSC_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_IDNTFR'), e.LGCL_ENTT_SN, '프로젝트 MCP 설정 식별자', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_LGCL_IDNTFR i where i.LGCL_ENTT_SN = e.LGCL_ENTT_SN and i.BSC_YN = true);
insert into TB_LGCL_IDNTFR_ATRB(LGCL_IDNTFR_ATRB_SN, LGCL_IDNTFR_SN, LGCL_ATRB_SN, SORT_ORD) select nextval('SQ_LGCL_IDNTFR_ATRB'), i.LGCL_IDNTFR_SN, a.LGCL_ATRB_SN, 1 from TB_LGCL_IDNTFR i join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = i.LGCL_ENTT_SN and a.ATRB_NM = '프로젝트 MCP 설정 일련번호' where i.LGCL_ENTT_SN = (select LGCL_ENTT_SN from TB_LGCL_ENTT where LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ENTT_NM = '프로젝트 MCP 설정') and i.IDNTFR_NM = '프로젝트 MCP 설정 식별자' and not exists (select 1 from TB_LGCL_IDNTFR_ATRB x where x.LGCL_IDNTFR_SN = i.LGCL_IDNTFR_SN);
insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ENTT_TBL_MPNG'), 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_MCP_STNG' where e.PRJ_SN = 0 and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN) and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_ENTT_TBL_MPNG mp join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and e.ENTT_NM = '프로젝트 MCP 설정' join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_NM = 'TB_PRJ_MCP_STNG' join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN where mp.PRJ_SN = 0 and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN) and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_REL'), 0, o.TBL_SN, t.TBL_SN, 'FK_PRJ_MCP_STNG_01', 'FK', 'USER', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL o join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ' where o.PRJ_SN = 0 and o.TBL_NM = 'TB_PRJ_MCP_STNG' and not exists (select 1 from TB_TBL_REL r where r.PRJ_SN = 0 and r.ORGNL_TBL_SN = o.TBL_SN and upper(r.REL_NM) = 'FK_PRJ_MCP_STNG_01');
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_PRJ_MCP_STNG' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'PRJ_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'PRJ_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_PRJ_MCP_STNG_01' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL'), 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'PRJ_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('PRJ_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('PRJ_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_PRJ' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_PRJ_MCP_STNG' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'PRJ_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_IDX'), 0, t.TBL_SN, 'UX_PRJ_MCP_STNG_01', null, true, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_MCP_STNG' and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_PRJ_MCP_STNG_01');
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_IDX_COL'), i.IDX_SN, c.COL_SN, 1 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_PRJ_MCP_STNG_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_PRJ_MCP_STNG' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 1);
insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL'), 0, s.SCHM_SN, 'TB_MCP_TKN', 'MCP 토큰', '프로젝트 범위 MCP 접근 토큰 (DEC-31) : 원문은 발급할 때 한 번만 보이고 해시만 저장한다. 만료 필수, 폐기 가능, 쓸 때마다 발급자의 지금 권한을 다시 확인한다', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_MCP_TKN', 'MCP_TKN_SN', 'MCP 토큰 일련번호', 'BIGINT', null, null, null, false, null, 1, false, null, true, false, true, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = 'MCP_토큰_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_MCP_TKN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'MCP_TKN_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_MCP_TKN', 'PRJ_SN', '프로젝트 일련번호', 'BIGINT', null, null, null, false, null, 2, false, null, true, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '프로젝트_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_MCP_TKN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_MCP_TKN', 'ACNT_SN', '계정 일련번호', 'BIGINT', null, null, null, false, null, 3, false, null, true, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '계정_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_MCP_TKN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'ACNT_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_MCP_TKN', 'TKN_NM', '토큰 명', 'VARCHAR', 100, null, null, false, null, 4, false, null, true, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '토큰_명'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_MCP_TKN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'TKN_NM');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_MCP_TKN', 'HASH_VL', '해시 값', 'VARCHAR', 255, null, null, false, null, 5, false, null, true, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '해시_값'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_MCP_TKN' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'HASH_VL');
