insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ENTT_TBL_MPNG'), 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_MCP_CALL_HSTRY' where e.PRJ_SN = 0 and e.ENTT_NM = 'MCP 호출 이력' and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN) and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_ENTT_TBL_MPNG mp join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and e.ENTT_NM = 'MCP 호출 이력' join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_NM = 'TB_MCP_CALL_HSTRY' join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN where mp.PRJ_SN = 0 and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN) and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
