insert into TB_LGCL_ENTT(LGCL_ENTT_SN, PRJ_SN, LGCL_MDL_SN, ENTT_NM, ENTT_EXPLN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ENTT'), 0, m.LGCL_MDL_SN, '논리 주제 영역 엔터티', '논리 엔터티의 주제 영역 소속 (M-6 후속 4차) : 엔터티당 0~1건. 엔터티 행과 따로 저장해 분류를 바꿔도 엔터티의 수정 일시·승인 상태가 바뀌지 않는다', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_MDL m where m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' and not exists (select 1 from TB_LGCL_ENTT e where e.LGCL_MDL_SN = m.LGCL_MDL_SN and e.ENTT_NM = '논리 주제 영역 엔터티');
