insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL'), 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'LGCL_MDL_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('LGCL_MDL_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('LGCL_MDL_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_LGCL_MDL' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_LGCL_SBTYP' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'LGCL_MDL_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');
