insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '비교' where t.PRJ_SN = 0 and t.TRM_NM = '컬럼_명_비교_값' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_STD_TRM_WORD'), t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '값' where t.PRJ_SN = 0 and t.TRM_NM = '컬럼_명_비교_값' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_COL'), 0, t.TBL_SN, 'TB_COL', 'COL_NM_CMPR_VL', '컬럼 명 비교 값', 'VARCHAR', 765, null, null, true, null, (select coalesce(max(c.SORT_ORD), 0) + 1 from TB_COL c where c.TBL_SN = t.TBL_SN), false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '컬럼_명_비교_값'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'COL_NM_CMPR_VL');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_ATRB'), mp.LGCL_ENTT_SN, '컬럼 명 비교 값', null, null, false, (select coalesce(max(a.SORT_ORD), 0) + 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = mp.LGCL_ENTT_SN), (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '컬럼_명_비교_값'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_ENTT_TBL_MPNG mp join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' where mp.PRJ_SN = 0 and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and a.ATRB_NM = '컬럼 명 비교 값');
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_ENTT_TBL_MPNG mp join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and a.ATRB_NM = '컬럼 명 비교 값' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'COL_NM_CMPR_VL' where mp.PRJ_SN = 0 and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN) and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_CNSTRT'), 0, t.TBL_SN, 'UX_COL_01', 'UNIQUE', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'TBL_SN') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'COL_NM_CMPR_VL') and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'UX_COL_01');
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'TBL_SN' where upper(k.CNSTRT_NM) = 'UX_COL_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 2 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'COL_NM_CMPR_VL' where upper(k.CNSTRT_NM) = 'UX_COL_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 2);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_CNSTRT'), 0, t.TBL_SN, 'CK_COL_01', 'CHECK', '(trim(translate(col_nm, chr(9) || chr(10) || chr(11) || chr(12) || chr(13), ''     '')) <> '''')', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'CK_COL_01');
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_COL' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'COL_NM' where upper(k.CNSTRT_NM) = 'CK_COL_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);
