update TB_COL set TASK_EXPLN = '확인 이력 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'SRC_VIEW_DFN_IDNTY_HSTRY_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이력이 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인한 정의의 출처 접속.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'SRC_CNTN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인한 출처 VIEW (번호로만 남는다).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'SRC_TBL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인할 때의 정의 해시 (원문은 남기지 않는다).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'HASH_VL' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의 원문을 확인한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'IDNTY_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

-- ---------- 예전 증분 V6 의 예제 (2026-11-18 세 번째 합침 — 스키마는 V0 의 같은 구간) ----------
-- 예전 증분 V6 : 선택형 내장 MCP — 프로젝트 MCP 설정·MCP 토큰·MCP 호출 이력 (DEC-31, 2026-11-16 — docs/completed/embedded-mcp-dec31.md).
-- 토큰 원문은 저장하지 않는다 (해시만). 기존 데이터는 바꾸지 않는다 : 설정 행이 없는 프로젝트는 MCP 가 꺼져 있다.
-- 예제(프로젝트 0)에 두 테이블을 용어 → 물리 → 논리 → 매핑 → 관계 → 인덱스 → 업무 설명 순서로 넣는다 (V3~V5 와 같은 규칙).
-- ---------- 예제 : 데이터 사전 (새 단어·새 용어) ----------
-- ---------- 예제 : 물리 모델 TB_PRJ_MCP_STNG ----------
-- ---------- 예제 : 논리 모델 프로젝트 MCP 설정 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 프로젝트 MCP 설정 ----------
-- ---------- 예제 : 관계 TB_PRJ_MCP_STNG (V6 의 FK 그대로, 삭제 규칙 포함) ----------
-- ---------- 예제 : 인덱스 TB_PRJ_MCP_STNG (V6 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 TB_PRJ_MCP_STNG ----------
update TB_TBL set TASK_EXPLN = '프로젝트 관리자가 외부 MCP 클라이언트의 읽기 전용 메타데이터 조회를 허용했는지 기록한다. 행이 없으면 꺼져 있다.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = 'MCP 설정 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'PRJ_MCP_STNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '설정이 속한 프로젝트 (프로젝트마다 한 행).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 프로젝트를 MCP 로 조회할 수 있는지 여부.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'ACTVTN_YN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
-- ---------- 예제 : 물리 모델 TB_MCP_TKN ----------
-- ---------- 예제 : 논리 모델 MCP 토큰 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 MCP 토큰 ----------
-- ---------- 예제 : 관계 TB_MCP_TKN (V6 의 FK 그대로, 삭제 규칙 포함) ----------
